import {run,createExecution} from './interpreter.js';
import {examples} from './examples.js';
const "'$=s=>document.querySelector(s), app=$('"'#app');
let mode='2d',page='studio',execution=null,timer=null,playing=false,view={zoom:1,panX:0,panY:0,yaw:-.65,pitch:.55}, challenge=null;
const initial=examples[0][4];let drafts={ '2d':localStorage.getItem('logo-draft-2d')??initial,'3d':localStorage.getItem('logo-draft-3d')??examples[7][4]};
let state={segments:[],pos:[0,0,0],heading:[0,1,0],right:[1,0,0],up:[0,0,1],done:true};
const challenges=[['Pierwszy ślad','Narysuj odcinek długości 100 do przodu.','np 100'],['Kwadrat','Narysuj kwadrat o boku 100, zaczynając od ruchu do przodu.','powtorz 4 [np 100 pw 90]'],['Trójkąt','Narysuj trójkąt równoboczny o boku 100, skręcając w prawo.','powtorz 3 [np 100 pw 120]'],['Schodek','Narysuj dwa odcinki: 80 do przodu, potem 80 w prawo.','np 80 pw 90 np 80'],['Krzyżyk','Narysuj linię 100, wróć bez rysowania i narysuj drugą w prawo.','np 100 pod ws 100 opu pw 90 np 100']];
let progress=JSON.parse(localStorage.getItem('logo-progress')||'{}');
function esc(s){return s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')}
function shell(){app.innerHTML="'`<header><div class="brand"><span class="brandmark">⌁</span><span>logomocja<small>PRACOWNIA ŻÓŁWIA</small></span></div><nav aria-label="Nawigacja"><button data-page="studio">Pracownia</button><button data-page="examples">Przykłady</button><button data-page="challenges">Wyzwania</button><button data-page="reference">Instrukcja</button></nav><div class="header-right"><span class="header-note"><i class="status-dot"></i>Twoje miejsce do tworzenia</span><button class="theme" id="theme" aria-label="Zmień motyw">◐</button></div></header><main id="main"></main><div id="toast" class="toast" hidden></div>`;document.querySelectorAll('"'[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()});"'$('"'#theme').onclick=()=>{let dark="'!document.body.classList.contains('"'dark');localStorage.setItem('logo-theme',dark?'dark':'light');setTheme()};setTheme();render()}
function setTheme(){let t=localStorage.getItem('logo-theme');document.body.classList.toggle('dark',t?t==='dark':matchMedia('(prefers-color-scheme: dark)').matches);if("'$('"'#canvas'))draw()}
function render(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='studio')studio();else if(page==='examples')examplePage();else if(page==='challenges')challengePage();else referencePage()}
